insert into public.proyectos_ideas (id, area, areas2, titulo, resumen, tipo, tiempo, horas, etiquetas, intencion, datos, prog, busca, ficha, orden) values
('contratos-de-matricula-que-compromisos-asume-un-estudiante','derecho',array['educacion','sociedad']::text[],'Contratos de matrícula: ¿qué compromisos asume un estudiante?','Explica qué compromisos adquiere una persona al matricularse en una institución educativa, como pagos, plazos, reglamentos, retiros y devoluciones, y arma una guía de preguntas para revisar antes de firmar.','Guía','~18 h',18,array['Matrícula','Educación']::text[],array['investigar','resolver']::text[],'publicos',NULL,'derecho educacion administracion economia trabajo social comunicaciones contabilidad psicologia lectura de reglamentos. analisis contractual. redaccion clara. pensamiento critico. reglamentos publicos. un editor de documentos. hoja de calculo.',$a14sld${"id": "contratos-de-matricula-que-compromisos-asume-un-estudiante", "area": "derecho", "areas2": ["educacion", "sociedad"], "titulo": "Contratos de matrícula: ¿qué compromisos asume un estudiante?", "resumen": "Explica qué compromisos adquiere una persona al matricularse en una institución educativa, como pagos, plazos, reglamentos, retiros y devoluciones, y arma una guía de preguntas para revisar antes de firmar.", "tipo": "Guía", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Matrícula", "Educación"], "intencion": ["investigar", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Educación", "Administración", "Economía", "Trabajo Social", "Comunicaciones", "Contabilidad", "Psicología"], "problema": ["Matricularse en un colegio, instituto o universidad privada implica aceptar condiciones sobre pagos, cuotas, mora, retiros, devoluciones y reglamentos. Muchas familias y estudiantes las conocen cuando surge un problema.", "Una guía que traduzca esas condiciones permite decidir con información."], "desarrollar": ["Con documentos públicos de instituciones, como reglamentos y modelos de contrato, identifica los compromisos más frecuentes y los puntos que generan conflictos, como retiros o cambios en pensiones.", "Redacta una guía en lenguaje sencillo con una lista de preguntas para revisar antes de matricularse y qué derechos tiene el estudiante ante cambios o incumplimientos."], "ampliaciones": [{"titulo": "Costo total del año", "aporta": "calcula cuánto paga una familia en total contando todos los conceptos."}, {"titulo": "Qué hacer ante una pensión impaga", "aporta": "explica pasos para negociar y reclamar."}, {"titulo": "Comparar instituciones", "aporta": "compara reglas de dos instituciones."}], "objetivos": ["Reconocer compromisos de la matrícula.", "Identificar puntos conflictivos.", "Explicar derechos.", "Elaborar una lista de verificación."], "habilidades": ["Lectura de reglamentos.", "Análisis contractual.", "Redacción clara.", "Pensamiento crítico."], "herramientas": ["Reglamentos públicos.", "Un editor de documentos.", "Hoja de cálculo."], "lineamientos": ["Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a un abogado o a la entidad competente.", "No nombres instituciones reales para criticarlas: describe lo que dicen los documentos públicos y cita la fuente.", "Verifica siempre en fuentes oficiales que la norma siga vigente y cita su fecha, porque las leyes cambian."], "otroSector": "La misma guía sirve para contratos de academias, de institutos, de guarderías o de programas de intercambio."}$a14sld$::jsonb,16),
('mapa-de-procesos-de-un-tramite-ciudadano-de-inicio-a-fin','derecho',array['industria','tecnologia']::text[],'Mapa de procesos de un trámite ciudadano, de inicio a fin','Sigue un trámite público frecuente desde que se inicia hasta que termina y dibuja su mapa de procesos: quién interviene, qué documentos pasan, cuánto tarda cada etapa y dónde se atasca.','Análisis','~24 h',24,array['Trámites','Procesos']::text[],array['investigar','crear']::text[],'publicos',NULL,'ingenieria industrial derecho administracion ingenieria de sistemas ciencias politicas economia comunicaciones estadistica mapeo de procesos. lectura de procedimientos. entrevistas. propuestas de mejora. un editor de diagramas. portales oficiales. hoja de calculo.',$a15sld${"id": "mapa-de-procesos-de-un-tramite-ciudadano-de-inicio-a-fin", "area": "derecho", "areas2": ["industria", "tecnologia"], "titulo": "Mapa de procesos de un trámite ciudadano, de inicio a fin", "resumen": "Sigue un trámite público frecuente desde que se inicia hasta que termina y dibuja su mapa de procesos: quién interviene, qué documentos pasan, cuánto tarda cada etapa y dónde se atasca.", "tipo": "Análisis", "tiempo": "~24 h", "horas": 24, "etiquetas": ["Trámites", "Procesos"], "intencion": ["investigar", "crear"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Ingeniería Industrial", "Derecho", "Administración", "Ingeniería de Sistemas", "Ciencias Políticas", "Economía", "Comunicaciones", "Estadística"], "problema": ["Un trámite parece un solo paso, pero en realidad es una cadena de etapas que involucran personas, oficinas, documentos y plazos. Casi nadie ve el recorrido completo, y por eso es difícil saber dónde se pierde el tiempo.", "Dibujar el proceso permite entenderlo, explicarlo y proponer mejoras."], "desarrollar": ["Elige un trámite frecuente, como obtener un certificado o una licencia, y con fuentes oficiales y entrevistas a personas que lo hayan hecho, lista cada paso, quién lo realiza, qué documento entra y sale y cuánto tarda.", "Dibuja un diagrama de flujo del proceso, marca los puntos donde se puede demorar o confundir y propón tres mejoras simples."], "ampliaciones": [{"titulo": "Tiempos medidos", "aporta": "estima el tiempo total y por etapa con los datos de varios casos."}, {"titulo": "Versión digital", "aporta": "propón cómo quedaría el trámite si fuera totalmente en línea."}, {"titulo": "Comparar con otro trámite", "aporta": "compara dos trámites para ver cuál es más simple."}], "objetivos": ["Reconstruir un trámite con fuentes.", "Dibujar un mapa de procesos.", "Detectar cuellos de botella.", "Proponer mejoras."], "habilidades": ["Mapeo de procesos.", "Lectura de procedimientos.", "Entrevistas.", "Propuestas de mejora."], "herramientas": ["Un editor de diagramas.", "Portales oficiales.", "Hoja de cálculo."], "lineamientos": ["Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a un abogado o a la entidad competente.", "Verifica siempre en fuentes oficiales que los requisitos y costos sigan vigentes y cita su fecha, porque los trámites cambian.", "Si entrevistas a personas, que sea voluntario y sin recoger datos personales, y no nombres a funcionarios."], "otroSector": "El mismo mapa de procesos sirve para procesos de admisión, atención en salud o gestión de pedidos en una empresa."}$a15sld$::jsonb,17),
('guia-paso-a-paso-para-obtener-o-actualizar-un-documento-de-ident','derecho',array['sociedad']::text[],'Guía paso a paso para obtener o actualizar un documento de identificación','Crea una guía ilustrada que explique cómo obtener o actualizar un documento de identidad, con requisitos, costos, lugares, tiempos y errores comunes.','Guía','~20 h',20,array['Identidad','Trámites']::text[],array['crear','resolver']::text[],'publicos',NULL,'derecho ciencias politicas trabajo social comunicaciones administracion diseno educacion ingenieria de sistemas lectura de procedimientos. diseno de guias. pruebas con usuarios. comunicacion clara. portales oficiales. un editor de infografias. un formulario de opinion.',$a16sld${"id": "guia-paso-a-paso-para-obtener-o-actualizar-un-documento-de-ident", "area": "derecho", "areas2": ["sociedad"], "titulo": "Guía paso a paso para obtener o actualizar un documento de identificación", "resumen": "Crea una guía ilustrada que explique cómo obtener o actualizar un documento de identidad, con requisitos, costos, lugares, tiempos y errores comunes.", "tipo": "Guía", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Identidad", "Trámites"], "intencion": ["crear", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Ciencias Políticas", "Trabajo Social", "Comunicaciones", "Administración", "Diseño", "Educación", "Ingeniería de Sistemas"], "problema": ["El documento de identidad abre la puerta a casi todo: matricularse, votar, abrir una cuenta o firmar un contrato. Sin embargo, obtenerlo o actualizarlo puede ser confuso, especialmente para quienes no conocen el sistema o no tienen acceso a internet.", "Una guía clara reduce errores y visitas innecesarias."], "desarrollar": ["Con información de la entidad oficial, reconstruye el procedimiento para obtener o actualizar el documento en distintas situaciones, como primera vez, renovación o cambio de datos, con requisitos, pagos y tiempos.", "Diseña una guía visual con un paso a paso, una lista de documentos, errores frecuentes y un ejemplo para cada situación, y pruébala con cinco personas."], "ampliaciones": [{"titulo": "Versión para menores", "aporta": "adapta la guía para el trámite de menores de edad."}, {"titulo": "Dónde hacerlo", "aporta": "añade un mapa de oficinas y alternativas de atención."}, {"titulo": "Versión en audio o video", "aporta": "crea una versión corta para personas con poco acceso a lectura."}], "objetivos": ["Reconstruir un procedimiento oficial.", "Diseñar una guía visual.", "Anticipar errores frecuentes.", "Probar con usuarios."], "habilidades": ["Lectura de procedimientos.", "Diseño de guías.", "Pruebas con usuarios.", "Comunicación clara."], "herramientas": ["Portales oficiales.", "Un editor de infografías.", "Un formulario de opinión."], "lineamientos": ["Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a un abogado o a la entidad competente.", "Verifica siempre en fuentes oficiales que los requisitos y costos sigan vigentes y cita su fecha, porque los trámites cambian.", "No incluyas números reales de documentos ni datos de personas en los ejemplos."], "otroSector": "La misma guía sirve para otros trámites frecuentes, como pasaporte, antecedentes, certificados o licencias."}$a16sld$::jsonb,18),
('comparando-requisitos-y-documentos-de-distintos-tramites-adminis','derecho',array['sociedad']::text[],'Comparando requisitos y documentos de distintos trámites administrativos','Compara qué documentos y requisitos piden distintos trámites, descubre cuáles se repiten, cuáles parecen innecesarios y por qué se piden.','Análisis','~20 h',20,array['Requisitos','Trámites']::text[],array['investigar']::text[],'publicos',NULL,'derecho administracion ciencias politicas ingenieria industrial ingenieria de sistemas estadistica economia trabajo social analisis comparativo. busqueda en fuentes oficiales. pensamiento critico. propuestas de mejora. hoja de calculo. portales oficiales. un editor de graficos.',$a17sld${"id": "comparando-requisitos-y-documentos-de-distintos-tramites-adminis", "area": "derecho", "areas2": ["sociedad"], "titulo": "Comparando requisitos y documentos de distintos trámites administrativos", "resumen": "Compara qué documentos y requisitos piden distintos trámites, descubre cuáles se repiten, cuáles parecen innecesarios y por qué se piden.", "tipo": "Análisis", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Requisitos", "Trámites"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Administración", "Ciencias Políticas", "Ingeniería Industrial", "Ingeniería de Sistemas", "Estadística", "Economía", "Trabajo Social"], "problema": ["Muchos trámites piden los mismos documentos una y otra vez, a veces con distintos formatos, copias o sellos. Eso cuesta tiempo y dinero a las personas, aunque algunos requisitos sí cumplen un propósito de verificación.", "Compararlos ayuda a entender qué es realmente necesario y qué podría simplificarse."], "desarrollar": ["Elige seis trámites de uso frecuente, reúne con fuentes oficiales los documentos y requisitos que piden, y arma una matriz que muestre cuáles se repiten.", "Investiga por qué se pide cada documento, identifica los que podrían obtenerse directamente de otras instituciones y propón cómo se reduciría la carga al ciudadano."], "ampliaciones": [{"titulo": "Costo del trámite", "aporta": "suma lo que gasta una persona en copias, traslados y pagos."}, {"titulo": "Simplificación", "aporta": "propón un documento único para varios trámites."}, {"titulo": "Normas de simplificación", "aporta": "investiga qué dicen las normas sobre no pedir documentos ya en poder del Estado."}], "objetivos": ["Reunir requisitos de varios trámites.", "Compararlos en una matriz.", "Entender el propósito de cada uno.", "Proponer simplificaciones."], "habilidades": ["Análisis comparativo.", "Búsqueda en fuentes oficiales.", "Pensamiento crítico.", "Propuestas de mejora."], "herramientas": ["Hoja de cálculo.", "Portales oficiales.", "Un editor de gráficos."], "lineamientos": ["Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a un abogado o a la entidad competente.", "Verifica siempre en fuentes oficiales que los requisitos y costos sigan vigentes y cita su fecha, porque los trámites cambian.", "Presenta las propuestas como ideas de mejora y no como críticas a funcionarios."], "otroSector": "La misma comparación sirve para requisitos de admisión, de becas o de postulación a prácticas."}$a17sld$::jsonb,19),
('que-informacion-necesita-una-persona-antes-de-iniciar-un-tramite','derecho',array['sociedad','educacion']::text[],'¿Qué información necesita una persona antes de iniciar un trámite?','Diseña una ficha de preguntas que una persona debería responder antes de empezar cualquier trámite: qué quiero lograr, quién lo hace, qué necesito, cuánto cuesta y cuánto demora.','Guía','~14 h',14,array['Información','Trámites']::text[],array['crear','resolver']::text[],'publicos',NULL,'derecho comunicaciones administracion trabajo social diseno psicologia educacion ingenieria de sistemas diseno de instrumentos. busqueda de informacion oficial. pruebas. comunicacion clara. un editor de documentos. portales oficiales. hoja de calculo.',$a18sld${"id": "que-informacion-necesita-una-persona-antes-de-iniciar-un-tramite", "area": "derecho", "areas2": ["sociedad", "educacion"], "titulo": "¿Qué información necesita una persona antes de iniciar un trámite?", "resumen": "Diseña una ficha de preguntas que una persona debería responder antes de empezar cualquier trámite: qué quiero lograr, quién lo hace, qué necesito, cuánto cuesta y cuánto demora.", "tipo": "Guía", "tiempo": "~14 h", "horas": 14, "etiquetas": ["Información", "Trámites"], "intencion": ["crear", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Comunicaciones", "Administración", "Trabajo Social", "Diseño", "Psicología", "Educación", "Ingeniería de Sistemas"], "problema": ["Muchos trámites fallan al principio: se va a la oficina equivocada, se lleva el documento incorrecto o se desconoce el costo. Esa información existe, pero está repartida y casi nadie la reúne antes de empezar.", "Una ficha previa de pocas preguntas ahorra visitas y frustración."], "desarrollar": ["Define entre ocho y diez preguntas esenciales para cualquier trámite y prueba la ficha con tres trámites distintos, buscando las respuestas en fuentes oficiales.", "Ajusta la ficha según qué preguntas fueron más difíciles de responder, y propón cómo podría integrarse a una página web de trámites."], "ampliaciones": [{"titulo": "Lista de documentos", "aporta": "añade un formato para marcar qué documentos ya se tienen."}, {"titulo": "Calendario del trámite", "aporta": "calcula fechas y plazos según el tipo."}, {"titulo": "Aplicación sencilla", "aporta": "crea una página que genere la ficha según el trámite."}], "objetivos": ["Definir preguntas clave.", "Probarlas con trámites reales.", "Ajustar la ficha.", "Pensar en su uso práctico."], "habilidades": ["Diseño de instrumentos.", "Búsqueda de información oficial.", "Pruebas.", "Comunicación clara."], "herramientas": ["Un editor de documentos.", "Portales oficiales.", "Hoja de cálculo."], "lineamientos": ["Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a un abogado o a la entidad competente.", "Verifica siempre en fuentes oficiales que los requisitos y costos sigan vigentes y cita su fecha, porque los trámites cambian."], "otroSector": "La misma ficha sirve para preparar una postulación, una cita médica o una matrícula."}$a18sld$::jsonb,20),
('como-solicitar-informacion-publica-a-una-institucion-del-estado','derecho',array['sociedad','tecnologia']::text[],'Cómo solicitar información pública a una institución del Estado','Explica cómo cualquier persona puede pedir información pública, qué datos se pueden solicitar, en qué plazo debe responder la institución y cómo redactar una solicitud clara.','Guía','~22 h',22,array['Transparencia','Acceso a la información']::text[],array['investigar','crear']::text[],'publicos',NULL,'derecho ciencias politicas comunicaciones administracion sociologia ingenieria de sistemas economia trabajo social lectura de normas. redaccion formal. busqueda en portales de transparencia. comunicacion clara. portales de transparencia. un editor de documentos. un editor de diagramas.',$a19sld${"id": "como-solicitar-informacion-publica-a-una-institucion-del-estado", "area": "derecho", "areas2": ["sociedad", "tecnologia"], "titulo": "Cómo solicitar información pública a una institución del Estado", "resumen": "Explica cómo cualquier persona puede pedir información pública, qué datos se pueden solicitar, en qué plazo debe responder la institución y cómo redactar una solicitud clara.", "tipo": "Guía", "tiempo": "~22 h", "horas": 22, "etiquetas": ["Transparencia", "Acceso a la información"], "intencion": ["investigar", "crear"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Ciencias Políticas", "Comunicaciones", "Administración", "Sociología", "Ingeniería de Sistemas", "Economía", "Trabajo Social"], "problema": ["En muchos países, cualquier ciudadano tiene derecho a pedir información a las instituciones públicas sobre presupuestos, contratos, obras o decisiones. Pero pocas personas lo saben y menos lo usan.", "Entender el procedimiento convierte ese derecho en una herramienta práctica."], "desarrollar": ["Con fuentes oficiales, reconstruye el procedimiento de solicitud de acceso a la información pública: dónde presentarla, qué debe contener, plazos de respuesta y costos de reproducción.", "Redacta una guía con un ejemplo de solicitud sobre un tema inventado, marca qué información suele estar publicada ya en portales y arma una lista de errores frecuentes."], "ampliaciones": [{"titulo": "Portales de transparencia", "aporta": "enseña a buscar primero lo ya publicado."}, {"titulo": "Respuestas posibles", "aporta": "explica qué significan las respuestas más comunes."}, {"titulo": "Ejercicio con un tema de interés", "aporta": "practica con una solicitud sobre un tema público real, si la autoridad lo permite."}], "objetivos": ["Conocer el derecho de acceso.", "Reconstruir el procedimiento.", "Redactar una solicitud clara.", "Explicar errores frecuentes."], "habilidades": ["Lectura de normas.", "Redacción formal.", "Búsqueda en portales de transparencia.", "Comunicación clara."], "herramientas": ["Portales de transparencia.", "Un editor de documentos.", "Un editor de diagramas."], "lineamientos": ["Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a un abogado o a la entidad competente.", "Verifica siempre en fuentes oficiales que los requisitos y costos sigan vigentes y cita su fecha, porque los trámites cambian.", "Pide solo información pública y no datos personales de terceros, y no uses la guía para hostigar a funcionarios."], "otroSector": "La misma guía sirve para consultar información de universidades públicas, empresas del Estado o comités vecinales."}$a19sld$::jsonb,21),
('que-puede-hacer-un-ciudadano-cuando-una-entidad-publica-no-respo','derecho',array['sociedad']::text[],'¿Qué puede hacer un ciudadano cuando una entidad pública no responde en el plazo?','Explica qué opciones existen cuando una institución pública no responde un trámite o una solicitud dentro de los plazos legales, como reiterar, reclamar o usar recursos.','Guía','~18 h',18,array['Plazos','Silencio administrativo']::text[],array['investigar','resolver']::text[],'publicos',NULL,'derecho ciencias politicas administracion comunicaciones trabajo social economia sociologia ingenieria industrial lectura de procedimientos. analisis de casos. redaccion formal. planificacion. portales oficiales. un editor de documentos. un editor de lineas de tiempo.',$a20sld${"id": "que-puede-hacer-un-ciudadano-cuando-una-entidad-publica-no-respo", "area": "derecho", "areas2": ["sociedad"], "titulo": "¿Qué puede hacer un ciudadano cuando una entidad pública no responde en el plazo?", "resumen": "Explica qué opciones existen cuando una institución pública no responde un trámite o una solicitud dentro de los plazos legales, como reiterar, reclamar o usar recursos.", "tipo": "Guía", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Plazos", "Silencio administrativo"], "intencion": ["investigar", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Ciencias Políticas", "Administración", "Comunicaciones", "Trabajo Social", "Economía", "Sociología", "Ingeniería Industrial"], "problema": ["A veces se presenta una solicitud y pasan semanas sin respuesta. Muchas personas no saben qué plazos tiene la entidad, qué ocurre cuando vence ese plazo ni qué pueden hacer a continuación.", "Conocer los caminos disponibles permite actuar sin recurrir a gestos desesperados."], "desarrollar": ["Con fuentes oficiales, resume qué plazos suelen aplicar, qué es el silencio administrativo, qué pasos puede dar el ciudadano y a qué instancia acudir.", "Elabora tres casos inventados donde no hay respuesta a tiempo y para cada uno diseña un plan de acción con pasos, plazos y modelos de escrito."], "ampliaciones": [{"titulo": "Línea de tiempo", "aporta": "dibuja los tiempos desde la presentación hasta el recurso."}, {"titulo": "Modelos de escritos", "aporta": "crea plantillas de seguimiento y reclamo."}, {"titulo": "Datos de demora", "aporta": "busca datos públicos sobre tiempos de respuesta de instituciones."}], "objetivos": ["Conocer plazos y silencio administrativo.", "Identificar recursos disponibles.", "Aplicarlos a casos.", "Comunicar con claridad."], "habilidades": ["Lectura de procedimientos.", "Análisis de casos.", "Redacción formal.", "Planificación."], "herramientas": ["Portales oficiales.", "Un editor de documentos.", "Un editor de líneas de tiempo."], "lineamientos": ["Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a un abogado o a la entidad competente.", "Verifica siempre en fuentes oficiales que los requisitos y costos sigan vigentes y cita su fecha, porque los trámites cambian.", "Trabaja con casos inventados o públicos y no incluyas datos personales de personas reales."], "otroSector": "La misma guía sirve para entender plazos en otros procedimientos, como los de una universidad o un seguro."}$a20sld$::jsonb,22),
('como-se-organiza-el-proceso-para-presentar-una-peticion-ante-una','derecho',array['sociedad']::text[],'¿Cómo se organiza el proceso para presentar una petición ante una institución pública?','Explica cómo presentar una petición o solicitud ante una entidad pública, qué debe contener, dónde se entrega y qué se puede esperar como respuesta.','Guía','~18 h',18,array['Peticiones','Participación']::text[],array['investigar','crear']::text[],'publicos',NULL,'derecho ciencias politicas administracion comunicaciones sociologia trabajo social ingenieria de sistemas educacion redaccion formal. lectura de procedimientos. pensamiento civico. comunicacion clara. un editor de documentos. portales oficiales. hoja de calculo.',$a21sld${"id": "como-se-organiza-el-proceso-para-presentar-una-peticion-ante-una", "area": "derecho", "areas2": ["sociedad"], "titulo": "¿Cómo se organiza el proceso para presentar una petición ante una institución pública?", "resumen": "Explica cómo presentar una petición o solicitud ante una entidad pública, qué debe contener, dónde se entrega y qué se puede esperar como respuesta.", "tipo": "Guía", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Peticiones", "Participación"], "intencion": ["investigar", "crear"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Ciencias Políticas", "Administración", "Comunicaciones", "Sociología", "Trabajo Social", "Ingeniería de Sistemas", "Educación"], "problema": ["Todo ciudadano puede dirigir peticiones a las instituciones, por ejemplo para pedir una mejora, una explicación o una reparación. Pero una petición mal planteada, sin destinatario correcto o sin sustento, suele quedar sin atención.", "Saber cómo organizarla aumenta mucho la posibilidad de ser escuchado."], "desarrollar": ["Con fuentes oficiales, describe qué es una petición, ante quién se presenta, qué datos debe incluir y cómo se da seguimiento.", "Redacta un modelo de petición sobre un tema inventado de tu barrio, indica a qué entidad se dirigiría y qué anexos conviene adjuntar, y valida el modelo con dos compañeros."], "ampliaciones": [{"titulo": "Petición colectiva", "aporta": "explica cómo presentar una petición con firmas de varios vecinos."}, {"titulo": "Seguimiento", "aporta": "diseña una hoja para registrar fechas y respuestas."}, {"titulo": "Versión en línea", "aporta": "revisa cómo presentar la petición por mesa de partes virtual."}], "objetivos": ["Conocer el derecho de petición.", "Redactar una petición clara.", "Identificar al destinatario correcto.", "Dar seguimiento."], "habilidades": ["Redacción formal.", "Lectura de procedimientos.", "Pensamiento cívico.", "Comunicación clara."], "herramientas": ["Un editor de documentos.", "Portales oficiales.", "Hoja de cálculo."], "lineamientos": ["Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a un abogado o a la entidad competente.", "Verifica siempre en fuentes oficiales que los requisitos y costos sigan vigentes y cita su fecha, porque los trámites cambian.", "Trabaja con casos inventados o públicos y no incluyas datos personales de personas reales."], "otroSector": "El mismo método sirve para redactar solicitudes a la universidad, a una empresa o a una organización."}$a21sld$::jsonb,23),
('como-saber-que-institucion-publica-es-responsable-de-un-servicio','derecho',array['sociedad','ciudades']::text[],'¿Cómo saber qué institución pública es responsable de un servicio o trámite?','Crea un método para averiguar qué institución atiende cada problema, como un hueco en la pista, un reclamo de agua, una denuncia o una licencia, y arma un directorio fácil de usar.','Guía','~18 h',18,array['Competencias','Instituciones']::text[],array['investigar','resolver']::text[],'publicos',NULL,'derecho ciencias politicas administracion geografia comunicaciones ingenieria de sistemas trabajo social sociologia investigacion en fuentes oficiales. organizacion de informacion. diseno de arboles de decision. pruebas con usuarios. portales oficiales. un editor de diagramas. hoja de calculo.',$a22sld${"id": "como-saber-que-institucion-publica-es-responsable-de-un-servicio", "area": "derecho", "areas2": ["sociedad", "ciudades"], "titulo": "¿Cómo saber qué institución pública es responsable de un servicio o trámite?", "resumen": "Crea un método para averiguar qué institución atiende cada problema, como un hueco en la pista, un reclamo de agua, una denuncia o una licencia, y arma un directorio fácil de usar.", "tipo": "Guía", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Competencias", "Instituciones"], "intencion": ["investigar", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Ciencias Políticas", "Administración", "Geografía", "Comunicaciones", "Ingeniería de Sistemas", "Trabajo Social", "Sociología"], "problema": ["Muchos problemas cotidianos se pierden porque la persona no sabe a quién dirigirse: ¿la municipalidad, la empresa de agua, una autoridad regional o un ministerio? Se pasa de ventanilla en ventanilla.", "Un método simple para ubicar al responsable ahorra mucho tiempo."], "desarrollar": ["Elige entre diez y quince problemas frecuentes de la vida diaria, y para cada uno averigua con fuentes oficiales qué institución es responsable y qué canal usar.", "Organiza el resultado en un directorio por tema y en un árbol de preguntas, como ¿tiene que ver con la calle?, ¿con el agua?, ¿con un servicio de salud?, y pruébalo con compañeros."], "ampliaciones": [{"titulo": "Mapa de competencias", "aporta": "dibuja quién hace qué entre municipalidad, región y nación."}, {"titulo": "Chatbot simple", "aporta": "diseña un flujo de preguntas que oriente al usuario."}, {"titulo": "Versión para tu distrito", "aporta": "adapta el directorio a un distrito concreto."}], "objetivos": ["Identificar responsables de servicios.", "Organizar un directorio.", "Diseñar un árbol de preguntas.", "Probar con usuarios."], "habilidades": ["Investigación en fuentes oficiales.", "Organización de información.", "Diseño de árboles de decisión.", "Pruebas con usuarios."], "herramientas": ["Portales oficiales.", "Un editor de diagramas.", "Hoja de cálculo."], "lineamientos": ["Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a un abogado o a la entidad competente.", "Verifica siempre en fuentes oficiales que los requisitos y costos sigan vigentes y cita su fecha, porque los trámites cambian.", "No publiques números de funcionarios ni datos personales; usa solo canales institucionales."], "otroSector": "El mismo directorio sirve para saber a quién acudir dentro de una universidad, un hospital o una empresa."}$a22sld$::jsonb,24),
('proteccion-de-datos-personales-en-la-vida-cotidiana','derecho',array['tecnologia','sociedad']::text[],'Protección de datos personales en la vida cotidiana','Descubre en qué situaciones del día a día se entregan datos personales, como una matrícula, una tienda o una app, y qué cuidados conviene tener en cada una.','Guía','~18 h',18,array['Datos personales','Privacidad']::text[],array['investigar','crear']::text[],'propios',NULL,'derecho ingenieria de sistemas comunicaciones psicologia ciencia de datos educacion sociologia administracion autoobservacion. analisis de riesgos. lectura de normas. comunicacion clara. una libreta o una hoja de calculo. portal de la autoridad de proteccion de datos. un editor de infografias.',$a23sld${"id": "proteccion-de-datos-personales-en-la-vida-cotidiana", "area": "derecho", "areas2": ["tecnologia", "sociedad"], "titulo": "Protección de datos personales en la vida cotidiana", "resumen": "Descubre en qué situaciones del día a día se entregan datos personales, como una matrícula, una tienda o una app, y qué cuidados conviene tener en cada una.", "tipo": "Guía", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Datos personales", "Privacidad"], "intencion": ["investigar", "crear"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Derecho", "Ingeniería de Sistemas", "Comunicaciones", "Psicología", "Ciencia de Datos", "Educación", "Sociología", "Administración"], "problema": ["Damos nuestros datos casi sin pensarlo: el DNI en una tienda, el número de celular para una oferta, la ubicación para una app. Cada dato por separado parece inofensivo, pero juntos dicen mucho sobre una persona.", "Reconocer cuándo y a quién se entregan ayuda a decidir qué compartir y qué no."], "desarrollar": ["Durante una semana anota en qué momentos te pidieron datos personales, qué datos fueron, quién los pidió y para qué decían usarlos, sin escribir los datos mismos.", "Clasifica las situaciones por nivel de riesgo, investiga con fuentes oficiales qué dice la norma sobre cada una y redacta una guía de cinco hábitos para cuidar tus datos."], "ampliaciones": [{"titulo": "Mapa de tus datos", "aporta": "dibuja un esquema de quiénes tienen qué datos tuyos."}, {"titulo": "Cuándo es obligatorio", "aporta": "distingue cuándo es obligatorio dar un dato y cuándo es opcional."}, {"titulo": "Campaña breve", "aporta": "diseña tres mensajes para tu universidad."}], "objetivos": ["Reconocer situaciones de entrega de datos.", "Clasificar riesgos.", "Conocer la norma básica.", "Redactar hábitos de cuidado."], "habilidades": ["Autoobservación.", "Análisis de riesgos.", "Lectura de normas.", "Comunicación clara."], "herramientas": ["Una libreta o una hoja de cálculo.", "Portal de la autoridad de protección de datos.", "Un editor de infografías."], "lineamientos": ["No escribas tus datos reales en el registro: anota solo el tipo de dato y la situación.", "Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a un abogado o a la autoridad competente.", "Verifica siempre en fuentes oficiales que la norma siga vigente y cita su fecha, porque las leyes cambian."], "otroSector": "El mismo ejercicio sirve para analizar qué datos recogen un colegio, una empresa o una organización."}$a23sld$::jsonb,25),
('que-informacion-compartimos-al-usar-servicios-digitales','derecho',array['tecnologia']::text[],'¿Qué información compartimos al usar servicios digitales?','Revisa qué datos entregas al usar aplicaciones y servicios digitales de uso común, como ubicación, contactos, fotos y hábitos, y qué permisos se les concede.','Investigación','~18 h',18,array['Servicios digitales','Datos']::text[],array['investigar']::text[],'propios',NULL,'ingenieria de sistemas derecho ciencia de datos comunicaciones psicologia sociologia estadistica educacion revision de configuraciones. analisis de datos. pensamiento critico. comunicacion clara. tu propio celular. hoja de calculo. un editor de infografias.',$a24sld${"id": "que-informacion-compartimos-al-usar-servicios-digitales", "area": "derecho", "areas2": ["tecnologia"], "titulo": "¿Qué información compartimos al usar servicios digitales?", "resumen": "Revisa qué datos entregas al usar aplicaciones y servicios digitales de uso común, como ubicación, contactos, fotos y hábitos, y qué permisos se les concede.", "tipo": "Investigación", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Servicios digitales", "Datos"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería de Sistemas", "Derecho", "Ciencia de Datos", "Comunicaciones", "Psicología", "Sociología", "Estadística", "Educación"], "problema": ["Una aplicación puede pedir acceso a la cámara, el micrófono, los contactos o la ubicación, y muchas personas aceptan sin pensar. Esos permisos permiten recoger más información de la que se imagina.", "Revisarlos permite descubrir qué se comparte sin necesidad."], "desarrollar": ["Elige cinco aplicaciones o servicios que uses y registra los permisos que tienen en tu celular, qué datos piden en el registro y cuáles parecen necesarios para su función.", "Clasifica los datos como necesarios, útiles o innecesarios, ajusta los permisos que no hacen falta y escribe qué cambió y qué conclusiones sacas."], "ampliaciones": [{"titulo": "Comparar sistemas", "aporta": "compara los permisos en dos sistemas operativos."}, {"titulo": "Datos de ubicación", "aporta": "estudia cómo se usa tu ubicación en una semana."}, {"titulo": "Resumen para otros", "aporta": "crea una guía de ajustes de privacidad para compañeros."}], "objetivos": ["Auditar permisos de aplicaciones.", "Clasificar datos.", "Ajustar configuraciones.", "Explicar los hallazgos."], "habilidades": ["Revisión de configuraciones.", "Análisis de datos.", "Pensamiento crítico.", "Comunicación clara."], "herramientas": ["Tu propio celular.", "Hoja de cálculo.", "Un editor de infografías."], "lineamientos": ["Revisa solo tus propios dispositivos y no muestres capturas con datos personales.", "No recomiendes desinstalar ni modificar sistemas de seguridad sin explicar los riesgos."], "otroSector": "El mismo análisis sirve para revisar los datos que recogen sitios web, dispositivos inteligentes o plataformas educativas."}$a24sld$::jsonb,26),
('analizando-y-comparando-politicas-de-privacidad-de-plataformas-d','derecho',array['tecnologia']::text[],'Analizando y comparando políticas de privacidad de plataformas de uso común','Lee y compara las políticas de privacidad de varias plataformas populares, descubre qué datos recogen, para qué los usan y con quién los comparten, y crea una guía para reconocer condiciones de privacidad.','Análisis','~24 h',24,array['Políticas de privacidad','Comparación']::text[],array['investigar']::text[],'publicos',NULL,'derecho ingenieria de sistemas ciencia de datos comunicaciones sociologia administracion psicologia educacion lectura critica de documentos. analisis comparativo. redaccion clara. diseno de guias. las politicas publicas de cada plataforma. hoja de calculo. un editor de infografias.',$a25sld${"id": "analizando-y-comparando-politicas-de-privacidad-de-plataformas-d", "area": "derecho", "areas2": ["tecnologia"], "titulo": "Analizando y comparando políticas de privacidad de plataformas de uso común", "resumen": "Lee y compara las políticas de privacidad de varias plataformas populares, descubre qué datos recogen, para qué los usan y con quién los comparten, y crea una guía para reconocer condiciones de privacidad.", "tipo": "Análisis", "tiempo": "~24 h", "horas": 24, "etiquetas": ["Políticas de privacidad", "Comparación"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Ingeniería de Sistemas", "Ciencia de Datos", "Comunicaciones", "Sociología", "Administración", "Psicología", "Educación"], "problema": ["Nadie lee las políticas de privacidad: son largas, técnicas y cambian. Pero ahí se dice qué datos se recogen, cuánto tiempo se guardan y con quién se comparten.", "Compararlas con una ficha ordenada permite ver diferencias reales entre servicios."], "desarrollar": ["Elige cuatro plataformas de uso común y para cada una lee su política de privacidad con una ficha de preguntas: qué datos recoge, para qué, con quién los comparte, cuánto tiempo los conserva y cómo se ejercen derechos.", "Compara en una tabla, resume en lenguaje sencillo lo más importante y elabora una guía con señales para reconocer políticas claras frente a políticas confusas."], "ampliaciones": [{"titulo": "Cambios en el tiempo", "aporta": "compara versiones antiguas y nuevas de una misma política."}, {"titulo": "Claridad del lenguaje", "aporta": "mide qué tan fácil es entender cada política."}, {"titulo": "Semáforo de privacidad", "aporta": "diseña un indicador sencillo para comparar."}], "objetivos": ["Leer políticas con una ficha.", "Compararlas.", "Resumir en lenguaje claro.", "Construir una guía de reconocimiento."], "habilidades": ["Lectura crítica de documentos.", "Análisis comparativo.", "Redacción clara.", "Diseño de guías."], "herramientas": ["Las políticas públicas de cada plataforma.", "Hoja de cálculo.", "Un editor de infografías."], "lineamientos": ["Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a un abogado o a la autoridad competente.", "Describe lo que dicen los documentos con su fecha, sin acusar a las empresas de prácticas que no puedas sustentar.", "Verifica siempre en fuentes oficiales que la norma siga vigente y cita su fecha, porque las leyes cambian."], "otroSector": "La misma lectura sirve para analizar términos y condiciones, contratos de servicios y reglamentos."}$a25sld$::jsonb,27),
('recomendaciones-para-proteger-tus-datos-personales-en-internet','derecho',array['tecnologia','educacion']::text[],'Recomendaciones para proteger tus datos personales en internet','Elabora recomendaciones prácticas, claras y no técnicas sobre qué información personal no conviene publicar en internet y cómo protegerla mejor.','Guía','~18 h',18,array['Seguridad','Datos personales']::text[],array['crear','resolver']::text[],'publicos',NULL,'ingenieria de sistemas derecho comunicaciones educacion psicologia diseno ciencia de datos sociologia investigacion. redaccion clara. diseno de guias. pruebas con usuarios. fuentes oficiales de ciberseguridad. un editor de infografias. un formulario de opinion.',$a26sld${"id": "recomendaciones-para-proteger-tus-datos-personales-en-internet", "area": "derecho", "areas2": ["tecnologia", "educacion"], "titulo": "Recomendaciones para proteger tus datos personales en internet", "resumen": "Elabora recomendaciones prácticas, claras y no técnicas sobre qué información personal no conviene publicar en internet y cómo protegerla mejor.", "tipo": "Guía", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Seguridad", "Datos personales"], "intencion": ["crear", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Ingeniería de Sistemas", "Derecho", "Comunicaciones", "Educación", "Psicología", "Diseño", "Ciencia de Datos", "Sociología"], "problema": ["Compartir fotos, ubicaciones, documentos o datos de familiares puede parecer inocente, pero puede usarse para fraudes, acoso o suplantación. Muchas personas no saben qué información es riesgosa.", "Recomendaciones simples, con ejemplos concretos, son más útiles que advertencias generales."], "desarrollar": ["Reúne con fuentes confiables qué tipos de información son riesgosos de publicar, como documentos de identidad, ubicación en tiempo real, datos de menores o información financiera, y por qué.", "Redacta una guía de recomendaciones con ejemplos de qué sí y qué no publicar, y pruébala con cinco personas para ver si se entiende y si cambiarían algo."], "ampliaciones": [{"titulo": "Versión para familias", "aporta": "adapta la guía para padres y adultos mayores."}, {"titulo": "Casos reales de riesgo", "aporta": "describe casos públicos de uso indebido de datos, sin nombres."}, {"titulo": "Lista de revisión de perfiles", "aporta": "crea una lista para revisar una cuenta de red social."}], "objetivos": ["Identificar información de riesgo.", "Explicar sus consecuencias.", "Formular recomendaciones.", "Probar la guía."], "habilidades": ["Investigación.", "Redacción clara.", "Diseño de guías.", "Pruebas con usuarios."], "herramientas": ["Fuentes oficiales de ciberseguridad.", "Un editor de infografías.", "Un formulario de opinión."], "lineamientos": ["Usa casos sin nombres y no incluyas datos reales en tus ejemplos.", "Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a un abogado o a la autoridad competente.", "No des instrucciones que enseñen a vulnerar cuentas de otras personas."], "otroSector": "Las mismas recomendaciones sirven para empresas pequeñas, colegios o clubes que manejan datos de personas."}$a26sld$::jsonb,28)
